"""Generated by the NL to Flow Diagram Encoder Pipeline."""

def multiplyMatrices(A, B, n, m, p):
    # A is n*m, B is m*p
    result = [[0 for _ in range(p)] for _ in range(n)]
    for i in range(0, n):
        for j in range(0, p):
            for k in range(0, m):
                result[i][j] = (result[i][j] + (A[i][k] * B[k][j]))
    return result
A = [
    [1, 2, 3],
    [4, 5, 6]
]

B = [
    [7, 8],
    [9, 10],
    [11, 12]
]

n = 2  # rows of A
m = 3  # cols of A / rows of B
p = 2  # cols of B

result = multiplyMatrices(A, B, n, m, p)
print(result)
